package cn.yulin.english;
import android.app.*;import android.content.*;import android.speech.tts.*;import android.widget.*;import java.util.*;
public final class SpeechSettings {
 private final Activity activity;private TextToSpeech tts;private boolean ready;
 public SpeechSettings(Activity a){activity=a;init();}
 private void init(){if(tts!=null)tts.shutdown();ready=false;tts=new TextToSpeech(activity,status->{ready=status==TextToSpeech.SUCCESS;if(ready)tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){}public void onError(String id){message("朗读失败，请检查英语语音包；联网语音还需要可用网络。");}});});}
 private void message(String s){activity.runOnUiThread(()->Toast.makeText(activity,s,Toast.LENGTH_LONG).show());}
 private SharedPreferences prefs(){return activity.getSharedPreferences("speech",0);}
 private List<Voice> voices(){List<Voice> list=new ArrayList<>();if(ready&&tts.getVoices()!=null)for(Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals("en"))list.add(v);list.sort((a,b)->Integer.compare(b.getQuality(),a.getQuality()));return list;}
 public void speak(String text){if(!ready){message("语音服务尚未就绪。可在发音设置中打开系统语音设置。");return;}String t=text.substring(0,Math.min(text.length(),2500));boolean chinese=t.matches("(?s).*[\\p{IsHan}].*");Locale locale=chinese?Locale.SIMPLIFIED_CHINESE:(prefs().getString("accent","US").equals("GB")?Locale.UK:Locale.US);if(tts.setLanguage(locale)<0){message("未安装对应语言的语音包，请打开发音设置。");return;}if(!chinese){String chosen=prefs().getString("voice","");Voice best=null;for(Voice v:voices()){if(v.getName().equals(chosen)){best=v;break;}if(best==null&&v.getLocale().getCountry().equals(locale.getCountry())&&!v.isNetworkConnectionRequired())best=v;}if(best!=null)tts.setVoice(best);else{message("未找到所选口音的可用语音，请在发音设置中选择已安装的英语语音。");return;}}tts.setPitch(1f);tts.setSpeechRate(prefs().getFloat("rate",1f));if(tts.speak(t,TextToSpeech.QUEUE_FLUSH,null,"yulin")==TextToSpeech.ERROR)message("朗读无法开始，请检查系统语音服务。");}
 public void settings(){LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(24,16,24,16);TextView note=new TextView(activity);note.setText("选择英式或美式语音。音色由设备语音引擎提供，安装高质量英语语音包可改善发音；联网语音会由设备语音服务处理朗读文本。更换系统引擎后请重新打开应用。");box.addView(note);Spinner accent=new Spinner(activity);accent.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"美式英语 US","英式英语 UK"}));accent.setSelection(prefs().getString("accent","US").equals("GB")?1:0);box.addView(accent);List<Voice> available=voices();List<String> labels=new ArrayList<>();labels.add("自动选择所选口音的离线英语语音");int selected=0;for(Voice v:available){labels.add(v.getLocale().toLanguageTag()+" · "+v.getName()+" · "+(v.isNetworkConnectionRequired()?"联网":"离线")+" · 质量 "+v.getQuality());if(v.getName().equals(prefs().getString("voice","")))selected=labels.size()-1;}Spinner voice=new Spinner(activity);voice.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,labels));voice.setSelection(selected);box.addView(voice);Spinner speed=new Spinner(activity);speed.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"0.85 倍（慢速）","1.0 倍（正常）","1.1 倍"}));float rate=prefs().getFloat("rate",1f);speed.setSelection(rate<1?0:rate>1?2:1);box.addView(speed);Button test=new Button(activity);test.setText("保存设置并试听");box.addView(test);Runnable save=()->{prefs().edit().putString("accent",accent.getSelectedItemPosition()==1?"GB":"US").putString("voice",voice.getSelectedItemPosition()==0?"":available.get(voice.getSelectedItemPosition()-1).getName()).putFloat("rate",new float[]{.85f,1f,1.1f}[speed.getSelectedItemPosition()]).apply();};test.setOnClickListener(v->{save.run();speak("Hello. Welcome to Rainforest English. Let's practise English together.");});new AlertDialog.Builder(activity).setTitle("发音与语速").setView(box).setPositiveButton("保存",(d,w)->save.run()).setNegativeButton("关闭",null).setNeutralButton("系统语音设置",(d,w)->{try{activity.startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){message("请到系统设置中搜索文字转语音或语言设置。");}}).show();}
 public void stop(){if(tts!=null)tts.stop();}public void destroy(){if(tts!=null)tts.shutdown();}
}
